package ru.balticdrive;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.ss.usermodel.CellType;
import java.nio.file.*;
import java.net.*;
import java.net.http.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static ru.balticdrive.Json.*;
public class RentalTest {
 @TempDir Path temp;
 Config config(boolean demo)throws Exception{return new Config(Path.of("").toAbsolutePath(),Map.of("DEMO_MODE",String.valueOf(demo),"ADMIN_TOKEN","a".repeat(64),"DATA_KEY","b".repeat(64),"DATA_DIR",temp.resolve("db").toString(),"FILES_DIR",temp.resolve("files").toString(),"PORT","0","BOT_ENABLED","false"),false);}
 String stamp(int days){return LocalDateTime.now(Bookings.ZONE).plusDays(days).withSecond(0).withNano(0).toString();}
 ObjectNode booking(String car,int start,int end){return obj("car",car,"start",stamp(start),"end",stamp(end));}
 ObjectNode person(){return obj("fullName","Тестовый Клиент","birthDate","1990-01-01","phone","+79991234567","passportSeries","0000","passportNumber","000000","passportIssuedBy","Тестовый орган выдачи","passportIssuedDate","2010-01-01","passportCode","000-000","registrationAddress","Тестовый адрес","licenseNumber","0000000000","licenseIssuedDate","2020-01-01","licenseExpires","2035-01-01","drivingSince","2010-01-01","categoryB",true,"consent",true,"consentVersion","2026-10-27-v1");}
 String claim(JsonNode b){return URI.create(s(b,"telegramUrl")).getQuery().substring(6);}
 String form(Bookings service,JsonNode b){return s(service.claim(claim(b),"101"),"formUrl").split("=")[1];}
 void failure(int code,org.junit.jupiter.api.function.Executable fn){assertEquals(code,assertThrows(Failure.class,fn).status);}
 @Test void datesAndTimeZone(){Instant now=Instant.parse("2026-01-01T00:00:00Z");JsonNode d=Bookings.dates("2026-01-02T10:00","2026-01-03T10:01",now);assertEquals(2,num(d,"days"));assertEquals("2026-01-02T08:00:00.000Z",s(d,"start"));assertEquals(1,num(Bookings.dates("2026-01-02T10:00","2026-01-03T10:00",now),"days"));failure(400,()->Bookings.dates("2026-02-30T10:00","2026-03-03T10:00",now));failure(400,()->Bookings.dates("2025-01-02T10:00","2025-01-03T10:00",now));}
 @Test void overlapClaimAndExpiry()throws Exception{Config c=config(true);try(Database db=new Database(c)){Bookings service=new Bookings(c,db);JsonNode b=service.create(booking("solaris",2,4));failure(409,()->service.create(booking("solaris",3,5)));String raw=form(service,b);failure(403,()->service.claim(claim(b),"202"));assertEquals(s(b,"id"),s(service.form(raw),"id"));failure(403,()->service.submit(raw,person()));db.execute("UPDATE bookings SET expires=? WHERE id=?",System.currentTimeMillis()-1,s(b,"id"));failure(410,()->service.claim(claim(b),"101"));assertNotNull(service.create(booking("solaris",3,5)));}}
 @Test void atomicConcurrentReservations()throws Exception{Config c=config(true);try(Database db=new Database(c);ExecutorService workers=Executors.newVirtualThreadPerTaskExecutor()){Bookings service=new Bookings(c,db);CountDownLatch start=new CountDownLatch(1);List<Future<Integer>> calls=new ArrayList<>();for(int i=0;i<8;i++)calls.add(workers.submit(()->{start.await();try{service.create(booking("rio",5,7));return 201;}catch(Failure e){return e.status;}}));start.countDown();int success=0,conflicts=0;for(var call:calls){int code=call.get();if(code==201)success++;if(code==409)conflicts++;}assertEquals(1,success);assertEquals(7,conflicts);}}
 @Test void encryptedSubmissionDocumentsAndPayments()throws Exception{Config c=config(false);try(Database db=new Database(c)){Bookings service=new Bookings(c,db);Documents docs=new Documents(c,db);JsonNode b=service.create(booking("polo",10,12));String raw=form(service,b);ObjectNode p=person();failure(400,()->service.submit(raw,p.deepCopy().put("consent",false)));failure(400,()->service.submit(raw,p.deepCopy().put("licenseExpires","2020-01-01")));p.put("fullName","Клиент <script>alert(1)</script>");assertEquals("pending",s(service.submit(raw,p),"status"));failure(410,()->service.submit(raw,p));JsonNode stored=db.get(s(b,"id"));assertFalse(s(stored,"pii").contains("passportNumber"));assertEquals(s(p,"fullName"),s(db.decrypt(s(stored,"pii")),"fullName"));failure(409,()->service.status(s(b,"id"),"completed"));service.status(s(b,"id"),"confirmed");service.status(s(b,"id"),"active");service.status(s(b,"id"),"completed");service.payment(s(b,"id"),obj("amount",1000));failure(400,()->service.payment(s(b,"id"),obj("amount",-1)));docs.refresh(s(b,"id"));String html=Files.readString(c.filesDir.resolve("contracts").resolve(s(b,"id")+".html"));assertTrue(html.contains("Экземпляр 1 из 2"));assertTrue(html.contains("Экземпляр 2 из 2"));assertTrue(html.contains("&lt;script&gt;"));assertFalse(html.contains("<script>"));assertEquals(2,html.split("Акт приёма-передачи и возврата к договору",-1).length-1);try(XSSFWorkbook w=new XSSFWorkbook(Files.newInputStream(c.filesDir.resolve("reports/clients.xlsx")))){assertEquals(3,w.getNumberOfSheets());assertEquals(s(p,"fullName"),w.getSheet("Заявки").getRow(1).getCell(2).getStringCellValue());assertEquals(CellType.STRING,w.getSheet("Заявки").getRow(1).getCell(3).getCellType());assertEquals(1000,w.getSheet("Статистика").getRow(3).getCell(1).getNumericCellValue());}}}
 @Test void retentionClearsDatabaseFilesAndReport()throws Exception{Config c=config(false);try(Database db=new Database(c)){Bookings service=new Bookings(c,db);Documents docs=new Documents(c,db);JsonNode b=service.create(booking("creta",10,12));service.submit(form(service,b),person());docs.refresh(s(b,"id"));service.status(s(b,"id"),"cancelled");db.execute("UPDATE bookings SET closed=? WHERE id=?",System.currentTimeMillis()-40L*86400000,s(b,"id"));docs.purge();assertTrue(db.get(s(b,"id")).path("pii").isNull());assertFalse(Files.exists(c.filesDir.resolve("contracts").resolve(s(b,"id")+".html")));}}
 @Test void httpApiAuthStaticFilesAndDownloads()throws Exception{Config c=config(true);try(Web web=new Web(c)){web.start();String base="http://127.0.0.1:"+web.port();HttpClient client=HttpClient.newHttpClient();assertEquals(401,request(client,base+"/api/admin/bookings","GET",null,null).statusCode());assertEquals(404,request(client,base+"/.env","GET",null,null).statusCode());assertEquals(404,request(client,base+"/data/rental.sqlite","GET",null,null).statusCode());assertEquals(200,request(client,base+"/","GET",null,null).statusCode());assertEquals(200,request(client,base+"/app.js","GET",null,null).statusCode());assertEquals(200,request(client,base+"/api/catalog","GET",null,null).statusCode());var bad=HttpRequest.newBuilder(URI.create(base+"/api/bookings")).header("Origin","https://evil.invalid").POST(HttpRequest.BodyPublishers.ofString("{}")).build();assertEquals(403,client.send(bad,HttpResponse.BodyHandlers.ofString()).statusCode());assertEquals(200,request(client,base+"/api/admin/demo","POST","{}",c.adminToken).statusCode());assertEquals(200,request(client,base+"/api/admin/report","GET",null,c.adminToken).statusCode());assertEquals(200,request(client,base+"/api/admin/bookings/demo-example/contract","GET",null,c.adminToken).statusCode());assertEquals(200,request(client,base+"/api/admin/bookings/demo-example/status","POST","{\"status\":\"cancelled\"}",c.adminToken).statusCode());assertEquals(200,request(client,base+"/api/admin/bookings/demo-example/person","DELETE",null,c.adminToken).statusCode());}}
 HttpResponse<byte[]> request(HttpClient client,String url,String method,String body,String key)throws Exception{var builder=HttpRequest.newBuilder(URI.create(url)).header("Content-Type","application/json");if(key!=null)builder.header("Authorization","Bearer "+key);builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body));return client.send(builder.build(),HttpResponse.BodyHandlers.ofByteArray());}
 @Test void botPrivateChatFormAndStatus()throws Exception{Config c=config(true);try(Database db=new Database(c)){Bookings service=new Bookings(c,db);List<JsonNode> sent=new ArrayList<>();Bot bot=new Bot(c,db,service,(method,payload)->{sent.add(payload);return obj("message_id",1);});JsonNode b=service.create(booking("rio",20,22));bot.handle(obj("message",obj("chat",obj("id",101,"type","group"),"text","/start "+claim(b))));assertEquals(0,sent.size());bot.handle(obj("message",obj("chat",obj("id",101,"type","private"),"text","/start "+claim(b))));assertTrue(s(sent.getFirst(),"text").contains("Не присылайте паспорт"));assertTrue(sent.getFirst().path("reply_markup").path("inline_keyboard").get(0).get(0).path("url").asText().contains("/#apply="));bot.handle(obj("message",obj("chat",obj("id",101,"type","private"),"text","/status")));assertTrue(s(sent.get(1),"text").contains("Ожидает Telegram"));}}
 @Test void productionRejectsInventedDetails(){assertThrows(IllegalStateException.class,()->new Config(Path.of("").toAbsolutePath(),Map.of("DEMO_MODE","false","ADMIN_TOKEN","a".repeat(64),"DATA_KEY","b".repeat(64)),true));}
}